package ai.eva.android.probe;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
/** Regression for old mixed-provider history, ordinary replay and compaction checkpoints. */
public final class ProviderHistoryWireTest {
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("eva-wire-").toFile();try{
 File home=new File(root,"home"),out=new File(home,"sessions/2026/11/08");out.mkdirs();String id=UUID.randomUUID().toString();JSONObject call=new JSONObject().put("type","function_call").put("id","item_foreign").put("call_id","call_keep").put("name","fixture").put("arguments","{\"id\":\"user-data-id\"}");JSONObject result=new JSONObject().put("type","function_call_output").put("call_id","call_keep").put("output","{\"id\":\"output-data-id\"}");JSONObject user=new JSONObject().put("type","message").put("id","item_message").put("role","user").put("content",new JSONArray().put(new JSONObject().put("type","input_image").put("image_url","data:image/png;base64,fixture")));
 JSONArray history=new JSONArray().put(user).put(call).put(result);String raw=new JSONObject().put("type","session_meta").put("payload",new JSONObject().put("id",id).put("model_provider","openai"))+"\n";
 for(int n=0;n<history.length();n++)raw+=new JSONObject().put("type","response_item").put("payload",history.getJSONObject(n))+"\n";
 raw+=new JSONObject().put("type","compacted").put("payload",new JSONObject().put("replacement_history",history).put("replacement_history_metadata",new JSONArray().put(new JSONObject().put("client_authored",true)).put(new JSONObject().put("client_authored",false)).put(new JSONObject().put("client_authored",false))))+"\n";File source=new File(out,"rollout-"+id+".jsonl");Files.write(source.toPath(),raw.getBytes("UTF-8"));
 JSONObject projected=ProviderHistoryProjection.project(home,out,"/root/sessions",id,"openai",false);if(!projected.getBoolean("needed"))throw new AssertionError("same-provider polluted history skipped");String path=projected.getString("path");File file=new File(out,path.substring(path.lastIndexOf('/')+1));List<String> lines=Files.readAllLines(file.toPath());JSONArray checkpoint=new JSONObject(lines.get(lines.size()-1)).getJSONObject("payload").getJSONArray("replacement_history");
 if(checkpoint.getJSONObject(0).has("id")||checkpoint.getJSONObject(1).has("id"))throw new AssertionError("foreign IDs survive checkpoint");
 if(!checkpoint.getJSONObject(1).getString("call_id").equals(checkpoint.getJSONObject(2).getString("call_id")))throw new AssertionError("tool pair lost");
 if(!checkpoint.getJSONObject(1).getString("arguments").contains("user-data-id")||!checkpoint.getJSONObject(2).getString("output").contains("output-data-id")||!checkpoint.getJSONObject(0).getJSONArray("content").getJSONObject(0).getString("image_url").endsWith("fixture"))throw new AssertionError("payload changed");
 if(!new String(Files.readAllBytes(source.toPath()),"UTF-8").equals(raw))throw new AssertionError("original changed");String copyId=new JSONObject(lines.get(0)).getJSONObject("payload").getString("id");if(ProviderHistoryProjection.project(home,out,"/root/sessions",copyId,"openai",false).getBoolean("needed"))throw new AssertionError("repeated projection");
 JSONObject b=ProviderHistoryProjection.project(home,out,"/root/sessions",copyId,"provider_b",true);if(b.getBoolean("needed"))throw new AssertionError("already portable history needlessly copied");System.out.println("PASS history wire: polluted same-provider replay/checkpoint, tool pairing, nested IDs/images, original bytes and stable resumed copy");
 }finally{try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new UncheckedIOException(e);}});}}}
}
